== C# implementation of Rabin Karp string search ==
--[[Special:Contributions/128.39.113.1|128.39.113.1]] ([[User talk:128.39.113.1|talk]]) 15:07, 25 November 2011 (UTC)--[[Special:Contributions/128.39.113.1|128.39.113.1]] ([[User talk:128.39.113.1|talk]]) 15:07, 25 November 2011 (UTC)
int RabinCarp(String text, String pattern)
{
    //If pattern is shorter than the text, exit.
    if (pattern.Length > text.Length)
        return -1;

    //Finds pattern's hash.
    int patternHash = 0;
    for (int i = 0; i < pattern.Length; i++)
        patternHash += pattern[i];

    //Makes init hash
    int textHash = 0;
    for (int i = 0; i < pattern.Length; i++)
        textHash += text[i];

    //Checks first position
    if (textHash == patternHash)
    {
        bool equal = true;
        for (int j = 0; j < pattern.Length; j++)
        {
            if (pattern[j] != text[j])
            {
                equal = false;
            }
        }
        if (equal)
            return 0;
    }

    for (int i = 0; i < text.Length - pattern.Length; i++)
    {
        //Find new rolling hash from text.
        textHash = textHash - text[i] + text[i + pattern.Length];
        //If the two hash values is equal, test if the strings is equal.
        if (textHash == patternHash)
        {
            bool equal = true;
            for (int j = 0; j < pattern.Length; j++)
            {
                if (pattern[j] != text[i+1 + j])
                {
                    equal = false;
                }
            }
            if (equal)
                return i+1;
        }
    }
    return -2;
}
